dtsPropsFor.ErrorBoundary:
children: React.ReactNode;
  /** Rendered in place of the subtree when it throws. A function receives `{ reset }` so the fallback can clear the error itself. */
  fallback: React.ReactNode | ((context: { reset: () => void }) => React.ReactNode);
  /** Changing this clears a tripped fallback (workflow id, active tab, …), so a render error doesn't strand the operator until a full reload. */
  resetKey?: string | number;
  /** Prefix for the diagnostic console line, e.g. `canvas` or `panel:runs`. */
  logTag?: string;
